// Phiên lưu phía MÁY CHỦ; cookie chỉ giữ một ID ngẫu nhiên, khó đoán
const sessions = new Map();
const newId = () => Array.from({ length: 16 }, () => Math.floor(Math.random() * 16).toString(16)).join("");

function createSession(userId, now) {
  const id = newId();
  sessions.set(id, { userId, expires: now + 7 * 24 * 3600 * 1000 });
  return id;
}

function verifySession(id, now) {
  const s = sessions.get(id);
  if (!s || s.expires < now) return null;
  return { userId: s.userId };
}

const t0 = 0;
const id = createSession(42, t0);
console.log(id.length, JSON.stringify(verifySession(id, t0 + 1000)));
console.log(verifySession("khong-co", t0));
console.log(verifySession(id, t0 + 8 * 24 * 3600 * 1000));

